/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the UTC hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const windowEnd = toIsoTimestamp(now);
      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  return now.getUTCHours() === org.settings.digestHourUtc;
}
/**
 * Barrel for the job layer.
 *
 * `instrumentation.ts` imports `startScheduler` from here; everything else in
 * the app talks to jobs by emitting an event, never by calling a runner
 * directly. The individual `run*Job` functions are exported for the admin
 * "run now" action and for the test suite.
 */
export {
  drain,
  enqueue,
  pendingCount,
  resetQueue,
} from "./queue";
export type { JobKind, QueuedJob } from "./queue";

export {
  isSchedulerRunning,
  startScheduler,
  stopScheduler,
  tick,
} from "./scheduler";

export { emptyJobResult } from "./types";
export type { JobResult } from "./types";

export { runCleanupArchivedJob } from "./cleanup-archived-job";
export { runDigestEmailJob, shouldRunForOrg } from "./digest-email-job";
export { runOverdueIssueJob } from "./overdue-issue-job";
export { runSearchReindexJob } from "./search-reindex-job";
export { runTrialExpiryJob } from "./trial-expiry-job";
export { runUsageRollupJob } from "./usage-rollup-job";
export { backoffMs, runWebhookDeliveryJob } from "./webhook-delivery-job";
/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
/**
 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
 */
import { createLogger } from "@/lib/logger";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type QueuedJob = {
  id: string;
  kind: JobKind;
  runAt: IsoTimestamp;
  attempts: number;
  payload: Readonly<Record<string, unknown>>;
};

export type JobKind =
  | "digest-email"
  | "overdue-issues"
  | "webhook-delivery"
  | "usage-rollup"
  | "search-reindex"
  | "cleanup-archived"
  | "trial-expiry";

/** Attempts after which a job is dropped rather than retried again. */
const MAX_ATTEMPTS = 5;

/** How many jobs `drain()` takes in one pass when no limit is given. */
const DEFAULT_DRAIN = 25;

const logger = createLogger("job-queue");

/**
 * The queue lives in module scope: Taskflow runs one server process and the
 * scheduler is started from `instrumentation.ts`, so there is no second
 * consumer to coordinate with. Swapping this for a real broker means
 * reimplementing these four functions and nothing else.
 */
const pending: QueuedJob[] = [];

/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
export function enqueue(job: QueuedJob): void {
  if (pending.some((queued) => queued.id === job.id)) return;
  pending.push(job);
}

/**
 * Runs everything that is due, oldest first. A handler that throws is put back
 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
 * — an infinitely retrying job is worse than a lost one.
 */
export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
  const now = new Date().toISOString();
  const due = pending
    .filter((job) => job.runAt <= now)
    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
    .slice(0, Math.max(0, limit));

  let completed = 0;

  for (const job of due) {
    remove(job.id);

    try {
      await runHandler(job);
      completed += 1;
    } catch (error) {
      const attempts = job.attempts + 1;

      if (attempts >= MAX_ATTEMPTS) {
        logger.error("job dropped after max attempts", {
          id: job.id,
          kind: job.kind,
          attempts,
        });
        continue;
      }

      pending.push({
        ...job,
        attempts,
        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
      });

      logger.warn("job retry scheduled", {
        id: job.id,
        kind: job.kind,
        attempts,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return completed;
}

export function pendingCount(): number {
  return pending.length;
}

/** Test hook: empties the queue. Never call this from application code. */
export function resetQueue(): void {
  pending.length = 0;
}

/** 1s, 2s, 4s, 8s … capped at one minute. */
function backoffMs(attempts: number): number {
  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
}

function remove(id: string): void {
  const at = pending.findIndex((job) => job.id === id);
  if (at >= 0) pending.splice(at, 1);
}

