  if (org === null || org.archivedAt === null) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (member === null || member.role !== "owner") return null;

  const result = toActionResult(
    new AlreadyArchivedError("Organization", org.id),
  ) as ActionResult<Organization>;
  return { ...result, submittedAt: new Date().toISOString() };
